//! Textures. The environment set (colour, normal and roughness maps) is
//! generated by `tools/make_textures.py` in the palette of
//! `art/environment-reference.png` and embedded in the binary, so no
//! platform loads files at runtime.

use bevy::asset::RenderAssetUsages;
use bevy::image::{CompressedImageFormats, ImageSampler, ImageType};
use bevy::prelude::*;

/// One surface's maps: colour (sRGB), tangent-space normals and packed
/// occlusion/roughness/metallic (both linear).
#[derive(Clone, Copy)]
pub struct Maps {
    pub color: &'static [u8],
    pub normal: &'static [u8],
    pub orm: &'static [u8],
}

/// The embedded environment textures.
pub mod env {
    use super::Maps;

    macro_rules! maps {
        ($name:literal) => {
            Maps {
                color: include_bytes!(concat!("../assets/env/", $name, ".png")),
                normal: include_bytes!(concat!("../assets/env/", $name, "_n.png")),
                orm: include_bytes!(concat!("../assets/env/", $name, "_orm.png")),
            }
        };
    }
    pub const WALLS: [Maps; 4] = [
        maps!("wall"),
        maps!("wall_mossy"),
        maps!("wall_cracked"),
        maps!("wall_carved"),
    ];
    pub const FLOORS: [Maps; 2] = [maps!("floor"), maps!("floor_mossy")];
    pub const CEILING: Maps = maps!("ceiling");
    pub const STAIRS: Maps = maps!("stairs");
    pub const ARCH: Maps = maps!("arch");
    pub const TRIM: Maps = maps!("trim");
    pub const VINES: Maps = maps!("vines");
    pub const FERN: Maps = maps!("fern");
    pub const SCONCE: Maps = maps!("sconce");
    pub const FLAME: &[u8] = include_bytes!("../assets/env/flame.png");
}

/// Decode an embedded colour PNG (sRGB, nearest-neighbour by default).
pub fn embedded(png: &[u8]) -> Image {
    decode(png, true)
}

/// Decode an embedded data PNG (normals, roughness): linear, not sRGB.
pub fn embedded_linear(png: &[u8]) -> Image {
    decode(png, false)
}

fn decode(png: &[u8], srgb: bool) -> Image {
    Image::from_buffer(
        png,
        ImageType::Extension("png"),
        CompressedImageFormats::NONE,
        srgb,
        ImageSampler::Default,
        RenderAssetUsages::RENDER_WORLD,
    )
    .expect("embedded textures are valid PNGs")
}

/// Add a full mip chain to a square, power-of-two sRGB RGBA image, so tiled
/// surfaces far away show their average colour instead of shimmering as you
/// move. Pixels are averaged in linear light, so distance doesn't darken.
pub fn with_mipmaps(mut image: Image) -> Image {
    let size = image.width();
    assert!(
        size.is_power_of_two() && image.height() == size,
        "square power of two"
    );
    let data = image.data.take().expect("decoded image has data");
    assert_eq!(data.len(), (size * size * 4) as usize, "RGBA8");
    let to_linear = |c: u8| (c as f32 / 255.0).powf(2.2);
    let to_srgb = |c: f32| (c.powf(1.0 / 2.2) * 255.0).round() as u8;
    let mut level: Vec<[f32; 4]> = data
        .chunks_exact(4)
        .map(|p| {
            [
                to_linear(p[0]),
                to_linear(p[1]),
                to_linear(p[2]),
                p[3] as f32 / 255.0,
            ]
        })
        .collect();
    let mut all = data;
    let (mut s, mut levels) = (size as usize, 1);
    while s > 1 {
        let half = s / 2;
        level = (0..half * half)
            .map(|i| {
                let (x, y) = (i % half * 2, i / half * 2);
                let px =
                    [(x, y), (x + 1, y), (x, y + 1), (x + 1, y + 1)].map(|(x, y)| level[y * s + x]);
                core::array::from_fn(|c| px.iter().map(|p| p[c]).sum::<f32>() / 4.0)
            })
            .collect();
        for p in &level {
            all.extend_from_slice(&[
                to_srgb(p[0]),
                to_srgb(p[1]),
                to_srgb(p[2]),
                (p[3] * 255.0).round() as u8,
            ]);
        }
        s = half;
        levels += 1;
    }
    image.texture_descriptor.mip_level_count = levels;
    image.data = Some(all);
    image
}
